SCHED_CONST:
# constant batch
B = %r


def run(env):
    for _ in range(env.n_segments):
        env.run_segment(B)

SCHED_PROBE:
# tries to reach outside its sandbox
import os, socket


def run(env):
    try:
        os.listdir("/app")
    except Exception:
        pass
    try:
        socket.create_connection(("127.0.0.1", 8765), 0.5)
    except Exception:
        pass
    import math
    B = math.sqrt(env.t_overhead * env.throughput)
    for _ in range(env.n_segments):
        env.run_segment(B)
